input.script:
phase("核对");
// 核对员的人设点名自己的模型；撰写员没点名，跟随 run 的 subagent_model。
const check = await agent("核对员", { model: "deepseek-v4-flash" }).ask("E2E_DWD_TASK_CHECK 核对材料，给出一句结论。");
phase("成文");
const text = await agent("撰写员").ask(`E2E_DWD_TASK_WRITE 根据核对结论成文：${check}`);
return { check, text };

phase("取证");
const probe = await agent("取证员").ask("E2E_DWD_TASK_PROBE 取证并给出一句结论。");
throw new Error(`E2E_DWD_FAIL_REASON 证据不足，无法继续：${probe.length}`);

phase("准备");
const prep = await agent("准备员").ask("E2E_DWD_TASK_PREP 准备材料，给出一句结论。");
phase("长跑");
const long = await agent("长跑员").ask(`E2E_DWD_TASK_LONG 基于准备结论长跑：${prep}`);
return { prep, long };
